import {educationBadges} from './career-opportunities-ui.js';
import {plainEducation,careerEducationSummary,careerEducationBullets,collegeBenefitPanel,careerTitle} from './career-presentation.js?v=0.31.0';
import {studyCostReference} from './financial-scenario-ui.js?v=0.31.0';
import {groupedOccupations} from './catalog-grouping-data.js?v=0.31.0';
import {escapeHTML as h,freshState} from './model.js?v=0.31.0';
import {careerFamilies,isTraining} from './guide-state.js?v=0.31.0';
import {fieldCareers} from './profile-journey.js?v=0.31.0';
import {fieldGlyph} from './profile-journey-ui.js?v=0.31.0';
import {occupationById,occupations} from './occupation-data.js?v=0.31.0';
import {occupationEssentials} from './occupation-essentials.js?v=0.31.0';
import {careerLanguage} from './career-language.js?v=0.31.0';
import {occupationProfilePanels,trainingCostPreview} from './profile-ui.js?v=0.31.0';
import {salaryPanel,salaryEvidenceLabel} from './salary-ui.js?v=0.31.0';
import {salaryAtStage,salaryPreviewStages,formatSalary} from './salary-progression.js?v=0.31.0';
import {clinicalTrainingTimeline,professionalCostPanel,graduateAidPanel} from './education-evidence-ui.js?v=0.31.0';
import {texasRequirements} from './texas-requirements.js?v=0.31.0';
import {freshLifestyle} from './lifestyle.js?v=0.31.0';
import {lifestyleOutput} from './lifestyle-ui.js?v=0.31.0';
const title=careerTitle;
const link=(r,t)=>`<a class="button secondary" href="#/${r}">${t}</a>`;
const intro=(t,c)=>`<div class="page-intro"><div><span class="eyebrow">THE CAREER LIBRARY</span><h1>${t}</h1><p>${c}</p></div></div>`;
const primaryGroup={emt:'public-safety','industrial-engineering':'building','urban-planning':'building',logistics:'transportation-production'};
const libraryURLs=html=>html.replaceAll('#/career/','#/learn/career/').replace(/#\/salary\/([a-z0-9-]+)\/([a-z0-9]+)\?from=[a-z-]+/g,'#/learn/salary/$1/$2');
export function careerLibraryPage(route,s,search=''){const [,part,id,stage]=route.split('/'),saved=s.careerLibrary?.saved||[];if(part==='career'){const o=occupationById(id);if(!o)return intro('Let’s find that career.','Browse a field below.')+link('learn/college','College careers →');const t=texasRequirements[id],otherTitles=groupedOccupations.filter(x=>o.pathIds.includes(x.path));return `${link(isTraining(o)?'learn/training':'learn/college','← Back to the library')}${intro(h(title(o)),'Get to know the work, the preparation, and life in Austin.')}${educationBadges(o)}<button class="button" data-action="library-save" data-id="${id}" aria-pressed="${saved.includes(id)}">${saved.includes(id)?'Saved for reading ✓':'Save for reading +'}</button><div class="career-quick-facts"><div><span>Entry pay · before tax</span><strong>${formatSalary(salaryAtStage(id))} / year</strong></div><div><span>How to get started</span><strong>${h(careerEducationSummary(o))}</strong></div></div><nav class="career-section-nav" aria-label="Career sections">${[['career-work','Work'],['career-education','Training'],['career-pay','Pay'],['career-notes','Notes']].map(([anchor,label])=>'<a href="#'+anchor+'" data-scroll-to="'+anchor+'">'+label+'</a>').join('')}</nav><section class="guide-work-panel" id="career-work"><h2>What you could do.</h2>${(careerLanguage[id]||[o.summary]).map(t=>'<p>'+h(t)+'</p>').join('')}</section><details class="more-info"><summary>Skills, qualities & working life</summary>${libraryURLs(occupationProfilePanels(o,freshState()))}</details>${otherTitles.length?'<details class="more-info"><summary>Other related job titles</summary><p>More specialized roles in related fields. Official profiles describe their own requirements.</p><ul>'+otherTitles.map(x=>'<li><a href="https://www.onetonline.org/link/summary/'+encodeURIComponent(x.soc)+'" target="_blank" rel="noopener noreferrer">'+h(x.title)+' ↗</a></li>').join('')+'</ul></details>':''}<section class="guide-input-panel" id="career-education"><h2>Education & requirements</h2><p><strong>${h(careerEducationSummary(o))}</strong></p><ul>${careerEducationBullets(o).map(t=>'<li>'+h(t)+'</li>').join('')}</ul>${clinicalTrainingTimeline(id)}${collegeBenefitPanel(o)}</section>${trainingCostPreview(id)}${professionalCostPanel(id)}${graduateAidPanel(id)}<details class="more-info"><summary>College costs & ways to pay</summary><p>2026–27 published references, before aid: UT Austin Texas-resident undergraduate tuition $10,858–$13,576 per academic year; ACC in-district tuition and fees $2,550 per 30-credit year. Living costs are separate. These are references, not a price for every program.</p><p>Grants and scholarships lower price. Loans fund it and must be repaid. Undergraduate support does not automatically cover professional school.</p><a href="#/source-review">Financial sources →</a></details>${libraryURLs(salaryPanel(id,{from:'career'}))}<section class="guide-input-panel" id="career-notes"><h2>My reading notes</h2><label for="library-note">What would you like to remember or learn more about?</label><textarea id="library-note" data-library-note="${id}" maxlength="6000">${h(s.careerLibrary?.notes?.[id]||'')}</textarea><p>Saved separately from the guided profile and personal plan.</p></section>`;}
 if(part==='salary'){const o=occupationById(id),amount=salaryAtStage(id,stage);if(!o||amount===null)return link('learn/college','← Career library');const inputs={...freshLifestyle(),careerId:id,band:'custom',gross:String(amount),netMode:'estimate'};return `${link('learn/career/'+id,'← '+h(title(o)))}${intro(formatSalary(amount)+' / year',h(title(o))+' · '+h(salaryPreviewStages(id).find(x=>x.key===stage)?.label||''))}<p><strong>${h(salaryEvidenceLabel(salaryPreviewStages(id).find(x=>x.key===stage)))}</strong></p><p><strong>Example: one adult renting alone with a used car.</strong> Separate from your plan.</p>${id==='physician'?'<p>Practice pay follows medical school and residency. Paid residency is a separate stage.</p>':''}<details class="more-info"><summary>More info · compare pay stages</summary><nav class="salary-preview-stages" aria-label="Salary examples">${salaryPreviewStages(id).map(x=>`<a href="#/learn/salary/${id}/${x.key}" ${x.key===stage?'aria-current="page"':''}>${h(x.label)}<b>${formatSalary(x.amount)}</b></a>`).join('')}</nav></details><p>Before any student-loan payments. Pay and costs are estimates.</p>${lifestyleOutput(inputs,{example:true}).replace(/<button[^>]*data-action="life-adjust"[^>]*>[\s\S]*?<\/button>/g,'')}`;}
 const mode=part==='training'?'training':part==='saved'?'saved':'college',query=search.trim().toLowerCase(),eligible=occupations.filter(o=>mode==='saved'?saved.includes(o.id):isTraining(o)===(mode==='training')).filter(o=>!query||[title(o),o.summary,...(o.aliases||[]),...(occupationEssentials[o.soc]?.aliases||[])].join(' ').toLowerCase().includes(query)||(query==='doctor'&&o.id==='physician')),seen=new Set();const card=o=>`<a class="library-career-card" href="#/learn/career/${o.id}"><h3>${h(title(o))}</h3>${educationBadges(o)}<p>${h(careerLanguage[o.id]?.[0]||o.summary.slice(0,140))}</p><p><strong>${formatSalary(salaryAtStage(o.id))}</strong> · estimated entry pay / year</p><span class="card-read-link">See this job →</span></a>`;return `${intro(mode==='college'?'Careers with college.':mode==='training'?'Careers without college.':'Saved for reading.','Read about jobs and save your favorites.')}<nav class="library-tabs" aria-label="Career library"><a href="#/learn/college" ${mode==='college'?'aria-current="page"':''}>Degree</a><a href="#/learn/training" ${mode==='training'?'aria-current="page"':''}>No degree</a><a href="#/learn/saved" ${mode==='saved'?'aria-current="page"':''}>Saved (${saved.length})</a></nav><label for="library-search">Find a career</label><input id="library-search" type="search" value="${h(search)}" placeholder="Doctor, dentist, design, electrician…">${mode==='training'?'<p>Start through training, experience, or an apprenticeship.</p>':''}<p>${eligible.length} ${eligible.length===1?'career':'careers'}</p>${careerFamilies.map(f=>{const rows=fieldCareers(f.id).filter(o=>eligible.includes(o)&&!seen.has(o.id)&&(!primaryGroup[o.id]||primaryGroup[o.id]===f.id));rows.forEach(o=>seen.add(o.id));return rows.length?`<details class="library-field" ${query?'open':''}><summary>${fieldGlyph(f.id)}${h(f.title)} <span>(${rows.length})</span></summary><div class="library-card-grid">${rows.map(card).join('')}</div></details>`:'';}).join('')}${eligible.some(o=>!seen.has(o.id))?'<section class="library-field"><h2>More careers</h2><div class="library-card-grid">'+eligible.filter(o=>!seen.has(o.id)).map(card).join('')+'</div></section>':''}${eligible.length?'':'<p>No careers found. Try a broader word or another section.</p>'}`;}
